#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long power;
    cin >> n >> power;
    vector<long long> t(n);
    for (int i = 0; i < n; i++) cin >> t[i];

    sort(t.begin(), t.end());
    long long lo = 0, hi = n - 1, score = 0, best = 0;
    while (lo <= hi) {
        if (power >= t[lo]) {
            power -= t[lo];
            lo++;
            score++;
            best = max(best, score);
        } else if (score > 0) {
            power += t[hi];
            hi--;
            score--;
        } else {
            break;
        }
    }
    cout << best << "\n";

    return 0;
}

